  <style>
    :root {
      color-scheme: dark;
      --bg: #090b12;
      --panel: #121725;
      --panel-light: #182033;
      --text: #eef3ff;
      --muted: #a7b0c5;
      --accent: #7c5cff;
      --accent-bright: #24d6ff;
      --border: rgba(255, 255, 255, 0.12);
      --shadow: rgba(0, 0, 0, 0.4);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(124, 92, 255, 0.32), transparent 32rem),
        radial-gradient(circle at bottom right, rgba(36, 214, 255, 0.18), transparent 28rem),
