      width: min(100%, 820px);
    }

    .quiz-card {
      background: linear-gradient(145deg, rgba(18, 23, 37, 0.96), rgba(11, 14, 24, 0.96));
      border: 1px solid var(--border);
      border-radius: 28px;
      box-shadow: 0 24px 70px var(--shadow);
      overflow: hidden;
    }

    .quiz-header {
      padding: 2rem;
      border-bottom: 1px solid var(--border);
      background: rgba(255, 255, 255, 0.03);
    }

