      margin: 0 0 0.65rem;
      font-size: clamp(2rem, 5vw, 3.25rem);
      letter-spacing: -0.05em;
      line-height: 1;
    }

    .intro {
      margin: 0;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 1.25rem;
      padding: 2rem;
    }

    .form-field {
      padding: 1.5rem;
      border: 1px solid var(--border);
      border-radius: 22px;
      background: rgba(255, 255, 255, 0.035);
    }

    .question-title {
      display: block;
      margin-bottom: 0.5rem;
      font-size: 1.15rem;
      font-weight: 750;
      line-height: 1.35;
    }

    .help-text {
      margin: 0 0 1rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .choices {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 0.8rem;
      margin-top: 1rem;
    }

    .choice {
      position: relative;
      display: flex;
      align-items: center;
      gap: 0.75rem;
      min-height: 3.35rem;
      padding: 0.9rem 1rem;
      border: 1px solid var(--border);
      border-radius: 16px;
      background: var(--panel-light);
      color: var(--text);
      cursor: pointer;
      transition: transform 160ms ease, border-color 160ms ease, background 160ms ease;
    }

    .choice:hover {
      transform: translateY(-2px);
      border-color: rgba(36, 214, 255, 0.55);
      background: #202a42;
    }

    .choice input {
      width: 1.05rem;
      height: 1.05rem;
      margin: 0;
      accent-color: var(--accent-bright);
    }

    .choice:has(input:checked) {
      border-color: rgba(36, 214, 255, 0.8);
      background: linear-gradient(135deg, rgba(124, 92, 255, 0.35), rgba(36, 214, 255, 0.16));
      box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.08);
    }

    .actions {
      display: flex;
      align-items: center;
      gap: 1rem;
      margin-top: 0.5rem;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.4rem;
      color: #071018;
      background: linear-gradient(135deg, var(--accent-bright), #9d84ff);
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 12px 30px rgba(36, 214, 255, 0.2);
      transition: transform 160ms ease, box-shadow 160ms ease;
    }

    button:hover {
      transform: translateY(-2px);
      box-shadow: 0 16px 38px rgba(36, 214, 255, 0.28);
    }

    #result {
      min-height: 1.5rem;
      margin: 0;
      color: var(--muted);
      font-weight: 650;
    }

    @media (max-width: 640px) {
      body {
        padding: 1rem;
      }

      .quiz-header,
      form {
        padding: 1.25rem;
      }

      .choices {
        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
<body>
  <main>
    <section class="quiz-card" aria-labelledby="quiz-title">
      <header class="quiz-header">
        <h1 id="quiz-title">Computer Languages Quiz</h1>
        <p class="intro">Choose every answer that fits each question, then submit your selections.</p>
      </header>

      <form id="quiz-form">
        <div class="form-field">
          <span class="question-title">1. Which of these are programming languages?</span>
          <p class="help-text">Select all actual programming languages. Some choices may be markup or styling languages instead.</p>
          <div class="choices">
            <label class="choice">
              <input type="checkbox" name="q1" value="Python">
              <span>Python</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q1" value="HTML">
              <span>HTML</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q1" value="JavaScript">
              <span>JavaScript</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q1" value="CSS">
              <span>CSS</span>
            </label>
          </div>
        </div>

        <div class="form-field">
          <span class="question-title">2. Which languages are commonly used for systems programming?</span>
          <div class="choices">
            <label class="choice">
              <input type="checkbox" name="q2" value="C">
              <span>C</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q2" value="Rust">
              <span>Rust</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q2" value="SQL">
              <span>SQL</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q2" value="Assembly">
              <span>Assembly</span>
            </label>
          </div>
        </div>

        <div class="form-field">
          <span class="question-title">3. Which languages can run directly in modern web browsers?</span>
          <div class="choices">
            <label class="choice">
              <input type="checkbox" name="q3" value="JavaScript">
              <span>JavaScript</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q3" value="WebAssembly">
              <span>WebAssembly</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q3" value="Ruby">
              <span>Ruby</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q3" value="PHP">
              <span>PHP</span>
            </label>
          </div>
        </div>

        <div class="actions">
          <button type="submit">Submit quiz</button>
          <p id="result" role="status" aria-live="polite"></p>
        </div>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#quiz-form");
    const result = document.querySelector("#result");

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const answeredCount = ["q1", "q2", "q3"].filter((name) => {
        return form.querySelectorAll(`input[name="${name}"]:checked`).length > 0;
      }).length;

      result.textContent = `You answered ${answeredCount} of 3 questions.`;
    });
  </script>
</body>
</html>
